using System.Collections.Generic;
using StrikeZone.Core;
using UnityEngine;
using UnityEngine.Rendering;

namespace StrikeZone.Game
{
    /// <summary>
    /// Creates and caches materials at runtime. Templates are generated by the editor
    /// build step into Resources/Generated so the right shaders are included in the APK;
    /// every runtime material is a clone of a template, which keeps the shader variant set
    /// small and SRP-Batcher-friendly. If templates are missing (editor play without setup)
    /// we fall back to Shader.Find, which always works inside the editor.
    /// </summary>
    public sealed class MaterialLibrary
    {
        public const string LitTemplatePath = "Generated/SZ_Lit";
        public const string SpriteTemplatePath = "Generated/SZ_Sprite";
        public const string SkyPath = "Generated/SZ_Sky";

        private static readonly int BaseColorId = Shader.PropertyToID("_BaseColor");
        private static readonly int ColorId = Shader.PropertyToID("_Color");
        private static readonly int BaseMapId = Shader.PropertyToID("_BaseMap");
        private static readonly int MainTexId = Shader.PropertyToID("_MainTex");
        private static readonly int SmoothnessId = Shader.PropertyToID("_Smoothness");
        private static readonly int GlossinessId = Shader.PropertyToID("_Glossiness");
        private static readonly int MetallicId = Shader.PropertyToID("_Metallic");

        private readonly Material _litTemplate;
        private readonly Material _spriteTemplate;
        private readonly Dictionary<string, Material> _cache = new Dictionary<string, Material>();
        private readonly GameDatabase _db;

        public Material Sky { get; private set; }

        public MaterialLibrary(GameDatabase db)
        {
            _db = db;
            _litTemplate = Resources.Load<Material>(LitTemplatePath);
            _spriteTemplate = Resources.Load<Material>(SpriteTemplatePath);
            Sky = Resources.Load<Material>(SkyPath);

            if (_litTemplate == null)
            {
                bool urp = GraphicsSettings.currentRenderPipeline != null;
                Shader shader = Shader.Find(urp ? "Universal Render Pipeline/Lit" : "Standard");
                if (shader == null) shader = Shader.Find("Standard");
                if (shader == null) shader = Shader.Find("Sprites/Default");
                _litTemplate = new Material(shader) { name = "SZ_Lit_Runtime" };
            }
            if (_spriteTemplate == null)
            {
                _spriteTemplate = new Material(Shader.Find("Sprites/Default")) { name = "SZ_Sprite_Runtime" };
            }
            if (Sky == null)
            {
                Shader skyShader = Shader.Find("Skybox/Procedural");
                if (skyShader != null) Sky = new Material(skyShader) { name = "SZ_Sky_Runtime" };
            }
        }

        public Material Lit(Color color, float smoothness = 0.25f, float metallic = 0f, Texture texture = null)
        {
            string key = "lit_" + ColorUtility.ToHtmlStringRGBA(color) + "_" + smoothness.ToString("0.00") + "_" +
                         metallic.ToString("0.00") + "_" + (texture != null ? texture.name : "none");
            Material m;
            if (_cache.TryGetValue(key, out m)) return m;

            m = new Material(_litTemplate) { name = key };
            SetColor(m, color);
            if (m.HasProperty(SmoothnessId)) m.SetFloat(SmoothnessId, smoothness);
            if (m.HasProperty(GlossinessId)) m.SetFloat(GlossinessId, smoothness);
            if (m.HasProperty(MetallicId)) m.SetFloat(MetallicId, metallic);
            SetTexture(m, texture);
            m.enableInstancing = true;
            _cache.Add(key, m);
            return m;
        }

        public Material Surface(string surfaceId)
        {
            string key = "surface_" + surfaceId;
            Material m;
            if (_cache.TryGetValue(key, out m)) return m;

            SurfaceDef def = _db.GetSurface(surfaceId);
            Color color;
            if (!ColorUtility.TryParseHtmlString(def.color, out color)) color = Color.gray;
            Texture2D tex = ProceduralTextures.ForSurface(def.id != null ? def.id : surfaceId);
            m = new Material(_litTemplate) { name = key };
            SetColor(m, color);
            if (m.HasProperty(SmoothnessId)) m.SetFloat(SmoothnessId, def.smoothness);
            if (m.HasProperty(GlossinessId)) m.SetFloat(GlossinessId, def.smoothness);
            if (m.HasProperty(MetallicId)) m.SetFloat(MetallicId, def.metallic);
            SetTexture(m, tex);
            m.enableInstancing = true;
            _cache.Add(key, m);
            return m;
        }

        /// <summary>Unlit, alpha-blended, vertex-coloured material (tracers, decals, flashes).</summary>
        public Material Sprite(string name, Texture texture)
        {
            string key = "sprite_" + name;
            Material m;
            if (_cache.TryGetValue(key, out m)) return m;
            m = new Material(_spriteTemplate) { name = key };
            if (texture != null) m.mainTexture = texture;
            _cache.Add(key, m);
            return m;
        }

        private static void SetColor(Material m, Color color)
        {
            if (m.HasProperty(BaseColorId)) m.SetColor(BaseColorId, color);
            if (m.HasProperty(ColorId)) m.SetColor(ColorId, color);
        }

        private static void SetTexture(Material m, Texture texture)
        {
            if (texture == null) return;
            if (m.HasProperty(BaseMapId)) m.SetTexture(BaseMapId, texture);
            if (m.HasProperty(MainTexId)) m.SetTexture(MainTexId, texture);
        }
    }
}
